import{_ as e,o as s,c as a,a as r}from"./app.83c7065c.js";const t="/assets/charles-1.02248453.png",i="/assets/charles-2.b7325ad3.png",l="/assets/charles-3.3c479a37.jpeg",p="/assets/charles-4.5cf01678.jpeg",c="/assets/charles-5.d7d002ff.jpeg",o="/assets/charles-6.ca0f711b.png",h="/assets/charles-7.4908e9d3.png",n="/assets/charles-8.b75dfcd4.png",d="/assets/charles-9.09e27eb6.png",_="/assets/charles-10.cd8db9e4.png",m="/assets/charles-11.e0e9209e.png",g="/assets/charles-12.80595522.png",f="/assets/charles-13-ios-1.a9a35a67.jpeg",u="/assets/charles-14-ios-2.5fc88013.jpeg",b="/assets/charles-15-ios-3.2153ffe4.jpeg",w="/assets/charles-16-ios-4.fac60727.jpeg",S="/assets/charles-17-ios-5.bbf1a2f3.jpeg",y="/assets/charles-19.e6df4af2.png",C="/assets/charles-18-ios-6.e5e8748f.jpeg",x="/assets/charles-20-android-1.5543c4ad.jpeg",k="/assets/charles-21-android-2.69d75218.jpeg",j="/assets/charles-22-android-3.7f9b57e2.jpeg",v="/assets/charles-23-android-4.76e315d3.jpeg",D=JSON.parse('{"title":"使用Charles抓包移动端网络请求","description":"","frontmatter":{"title":"使用Charles抓包移动端网络请求","date":"2019-09-07"},"headers":[],"relativePath":"2019/charles-mobile-packet-capture.md","lastUpdated":1786184870000}'),P={name:"2019/charles-mobile-packet-capture.md"},T=r('<h3 id="写在前面" tabindex="-1">写在前面 <a class="header-anchor" href="#写在前面" aria-hidden="true">#</a></h3><p>这是4个月前的一篇简要工作记录，重新编辑整理了一下，算是自己技能成长的一个见证。</p><p>可以抓包移动端网络请求的工具很多，windows下有fiddler和wireshark，Mac下有Charlse和Surge for Mac（Surge iOS版甚至可以在iOS设备上直接抓包，功能非常强大）。</p><p>因为目前使用Mac，所以本文主要介绍如何使用Charles在Mac上进行抓包。</p><blockquote><p>注意： <strong>以下全程，请保持电脑和手机在同一个局域网内</strong></p></blockquote><h3 id="抓包普通请求" tabindex="-1">抓包普通请求 <a class="header-anchor" href="#抓包普通请求" aria-hidden="true">#</a></h3><blockquote><p>这部分iOS和Android方法类似，以iOS为例说明</p></blockquote><ol><li><p>打开Charles代理设置窗口，点击 Proxy -&gt; Proxy Settings</p><p><img src="'+t+'" alt="charles 1"></p></li><li><p>设置代理端口号，勾选 Enable transparent HTTP proxying，并设置一个端口号，比如8888</p><p><img src="'+i+'" alt="charles 2"></p></li><li><p>手机端配置</p><ul><li>打开 设置-&gt; 无线局域网，点击已连接wif的蓝色图标，图中红圈处</li></ul><p><img src="'+l+'" alt="charles 3"></p><ul><li>HTTP代理选手动配置</li></ul><p><img src="'+p+'" alt="charles 4"></p><ul><li>服务器配置为电脑的IP，端口设为之前charles配置的端口</li></ul><p><img src="'+c+'" alt="charles 5"></p></li><li><p>允许手机连接charles</p><p>这个时候随便访问一个网页，charles就会提示，选择“允许”</p><p><img src="'+o+'" alt="charles 6"></p><p>如果不小心关掉了也没关系，打开Proxy -&gt; Access Control Settings，添加手机的IP就可以了</p><p><img src="'+h+'" alt="charles 7"></p><p><img src="'+n+'" alt="charles 8"></p></li></ol><p>之后手机上的任何http请求，都可以被charles抓包查看了，Done.</p><h3 id="抓包https请求" tabindex="-1">抓包https请求 <a class="header-anchor" href="#抓包https请求" aria-hidden="true">#</a></h3><p>上面的配置只能抓包http请求，但是现在主要网站大都是https的，请求数据会显示为乱码，不可读。需要额外配置让charles可以抓包https的请求。根据官网的说明，抓包https请求需要在手机上安装charles证书。</p><p>为什么需要安装证书呢？官方的说明如下：</p><blockquote><p><a href="https://www.charlesproxy.com/documentation/proxying/ssl-proxying/" target="_blank" rel="noreferrer">SSL Proxying</a></p><p>Charles does this by becoming a man-in-the-middle. Instead of your browser seeing the server’s certificate, Charles dynamically generates a certificate for the server and signs it with its own root certificate (the Charles CA Certificate). Charles receives the server’s certificate, while your browser receives Charles’s certificate. Therefore you will see a security warning, indicating that the root authority is not trusted. If you add the Charles CA Certificate to your trusted certificates you will no longer see any warnings – see below for how to do this.</p><p>Charles still communicates via SSL to the web server. The communication is SSL (encrypted) from web browser to Charles and also SSL (encrypted) from Charles to the web server.</p></blockquote><p>这个抓包本质上是一种中间人攻击 (Man in the Middle Attack)。</p><p>只不过单纯抓包并没有篡改数据，只是charles作为代理和服务端通信，然后转发数据和charles动态生成的证书给手机。如果不安装证书，手机浏览器会提示证书不可信，以存在安全风险为由，拒绝接受charles发回的数据。</p><p>理论上，charles当然也可以篡改数据后再发给手机，似乎某些更高级的功能就是基于此实现的。这不是本文的主题了，以后有机会再写。</p><p>废话结束，下面继续说明如何安装证书。</p><h4 id="安装证书" tabindex="-1">安装证书 <a class="header-anchor" href="#安装证书" aria-hidden="true">#</a></h4><h5 id="charles启用ssl代理功能" tabindex="-1">Charles启用SSL代理功能 <a class="header-anchor" href="#charles启用ssl代理功能" aria-hidden="true">#</a></h5><ul><li><p>启动SSL代理</p><p><img src="'+d+'" alt="charles 9"></p></li><li><p>配置要代理的网站域名和端口，以下以V2EX为例，访问接口 <a href="https://www.v2ex.com/api/nodes/show.json?name=jobs" target="_blank" rel="noreferrer">https://www.v2ex.com/api/nodes/show.json?name=jobs</a></p><p><img src="'+_+'" alt="charles 10"></p></li><li><p>打开需要手机访问安装证书的网站</p><p><img src="'+m+'" alt="charles 11"></p></li><li><p>根据弹窗提示找到网址</p><p><img src="'+g+'" alt="charles 12"></p></li></ul><h5 id="手机端配置" tabindex="-1">手机端配置 <a class="header-anchor" href="#手机端配置" aria-hidden="true">#</a></h5><blockquote><p>证书安装在iOS和Android两端不同，手机端的配置分为两部分写</p></blockquote><h5 id="ios" tabindex="-1">iOS <a class="header-anchor" href="#ios" aria-hidden="true">#</a></h5><ul><li><p>手机Safari打开<code>https://chls.pro/ssl</code>这个网址下载证书</p><p><img src="'+f+'" alt="charles 13"></p></li><li><p>根据提示下载证书，返回设置，在已下载描述文件中找到该证书</p><p><img src="'+u+'" alt="charles 14"></p></li><li><p>安装证书</p><p><img src="'+b+'" alt="charles 15"></p></li><li><p>关于本机开启信任证书</p><p><img src="'+w+'" alt="charles 16"></p></li><li><p>happy抓包</p><p><img src="'+S+'" alt="charles 17"></p><p><img src="'+y+'" alt="charles 19"></p></li><li><p>如果不开启信任证书</p><p><img src="'+C+'" alt="charles 18"></p></li></ul><h5 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-hidden="true">#</a></h5><ul><li><p>前三步和iOS相同，手机Chrome打开网址下载证书并安装</p></li><li><p>安装成功之后各个安卓手机有所不同了，我用的坚果pro2</p><p>坚果pro2： 设置 - 解锁与安全 - 高级设置 - 受信任的凭据 - 用户tab</p><p><img src="'+x+'" alt="charles 20"></p><p><img src="'+k+'" alt="charles 21"></p></li><li><p>如果安装失败，可以下载证书文件到本地，选择从存储设备安装（可以参考<a href="https://cosmeapp.github.io/2017/09/26/install-charles-certificate-android/" target="_blank" rel="noreferrer">这篇</a>）</p><ul><li>坚果pro2: 设置 - 解锁与安全 - 高级设置 - 从存储设备安装，见上图</li></ul></li><li><p>happy抓包</p><p><img src="'+j+'" alt="charles 22"></p></li><li><p>如果没有安装证书</p><p><img src="'+v+'" alt="charles 23"></p></li></ul><h4 id="记录完毕-收工" tabindex="-1">记录完毕，收工 <a class="header-anchor" href="#记录完毕-收工" aria-hidden="true">#</a></h4>',27),A=[T];function q(O,M,I,L,E,V){return s(),a("div",null,A)}const N=e(P,[["render",q]]);export{D as __pageData,N as default};
